def bank_px(v):
    """0.1.5: a 0.1.4 page size x 1.1, rounded half up in integer maths (16 -> 18, 15 -> 17, 44 -> 48, 172 -> 189, 4 -> 4)."""
    return (v * 11 + 5) // 10


