def bank_outer(mk):
    """(outer width, outer height) of a markup's ROOT element, read from its own Anchor: Width + Left + Right (+ 2 x Horizontal /
    Full) and Height + Top + Bottom (+ 2 x Vertical / Full); None where the root sets no Width / Height. KIT-GAP (review 2): the
    kit builders do not report their outer size, so the budget reads it back out of the markup instead of typing "+ 12" by hand."""
    r = SUI.render(mk)
    i = r.index("{")
    j = r.find("{", i + 1)
    own = r[i + 1:] if j < 0 else r[i + 1:j]
    m = re.search(r"Anchor: \(([^)]*)\)", own)
    a = dict((k, int(v)) for k, v in re.findall(r"(Width|Height|Left|Right|Top|Bottom|Horizontal|Vertical|Full): (-?\d+)",
                                                 m.group(1))) if m else {}
    hm = a.get("Left", 0) + a.get("Right", 0) + 2 * (a.get("Horizontal", 0) + a.get("Full", 0))
    vm = a.get("Top", 0) + a.get("Bottom", 0) + 2 * (a.get("Vertical", 0) + a.get("Full", 0))
    return (a["Width"] + hm if "Width" in a else None), (a["Height"] + vm if "Height" in a else None)


def bank_filled(ap, parent, axis, avail, what, cross=None):
    """Assert that the direct children of `parent` fill it exactly: their outer widths (axis "w", a LayoutMode Left row) or outer
    heights (axis "h", a LayoutMode Top column) sum to `avail` px (no FlexWeight filler); cross = the row height every child of a
    Left row must fit in."""
    kids = [bank_outer(mk) for p, mk in ap if p == parent]
    assert kids, "%s has no children" % what
    sizes = [k[0] if axis == "w" else k[1] for k in kids]
    assert None not in sizes, "%s: a child without a fixed %s" % (what, "Width" if axis == "w" else "Height")
    left = SUI.fit(sizes, avail, what)
    assert left == 0, "%s must be filled exactly: %s = %d of %d px" % (what, sizes, sum(sizes), avail)
    if cross is not None:
        assert all(k[1] is not None and k[1] <= cross for k in kids), "%s: a child is taller than the %d px row: %s" % (what, cross, kids)


def bank_anchor(mk):
    """0.1.5: {Width / Height / Left / Right / Top / Bottom / ...: int} of a markup's ROOT element, read from its own Anchor (the
    same reading as bank_outer)."""
    r = SUI.render(mk)
    i = r.index("{")
    j = r.find("{", i + 1)
    own = r[i + 1:] if j < 0 else r[i + 1:j]
    m = re.search(r"Anchor: \(([^)]*)\)", own)
    return dict((k, int(v)) for k, v in re.findall(r"(Width|Height|Left|Right|Top|Bottom|Horizontal|Vertical|Full): (-?\d+)",
                                                   m.group(1))) if m else {}


def bank_spans(ap, row):
    """0.1.5: [(id or None, x0, x1)] - where each direct child of the LayoutMode Left row `row` sits (Left margin + Width, then its
    Right margin), read back out of the markup: proves the captions sit exactly under their controls."""
    out, x = [], 0
    for p, mk in ap:
        if p != row:
            continue
        a = bank_anchor(mk)
        mt = re.match(r"\s*[A-Za-z]+(?:\s+#([A-Za-z0-9]+))?\s*\{", SUI.render(mk))
        x0 = x + a.get("Left", 0)
        out.append((mt.group(1), x0, x0 + a["Width"]))
        x = x0 + a["Width"] + a.get("Right", 0)
    return out


def bank_page():
    """(shell, sets): BankPage's markup from the kit - 0.1.4's page with the controls row reordered (Skyy: the amount box between
    Deposit and Withdraw) and every size x 1.1 (bank_px). The page height is still the sum of its parts (the body, every row and
    every well filled exactly, read back out of the markup), the captions sit under their controls, every button label fits, every
    margin is a vanilla step x 1.1, only proven properties - asserted, like every 0.1.3 id and b.set target."""
    sh = SUI.page_shell("SkyyBankF", BANK_W, BANK_H, "Bank", pad=BANK_PAD, body_id="SkyyBank")   # the 0.1.3 root is the body
    ap, body, W = sh.appends, sh.body, sh.inner_w
    n_frame = len(ap)
    m = bank_px                           # 0.1.4's size -> 0.1.5's (x 1.1)
    FS = BANK_FS
    BTN, WIDE, BH, BSZ = BANK_BTN, BANK_BTN_WIDE, BANK_BTN_H, BANK_BTN_SIZE
    PAD = m(SUI.WELL_PAD)                 # 9: the well's padding (8, WorldEventPanelPage #Summary) x 1.1
    assert BH == m(SUI.BTN_H) == SUI.BUTTON_SIZES[BSZ][1], "the kit's big button (%d) must be the 44 px button x 1.1" % BH
    for _k in ("message", "status"):
        assert 2 * SUI.line_height(FS[_k]) <= BANK_TWO_LINES, "two %d px lines do not fit %d px" % (FS[_k], BANK_TWO_LINES)

    # 1. profile / hint line (0.1.3 #SkyyBSub = subText(u)): the vanilla wrapped message, two lines high (review finding 6)
    ap.append((body, SUI.label("SkyyBSub", "", "message", h=BANK_TWO_LINES, size=FS["message"], anchor={"bottom": m(12)})))

    # 2. PURSE and BANK: two wells side by side; in each a centred @Subtitle, the number (the kit display, Default font), a caption
    head_h, num_h, cap_h = m(25), m(42), m(25)
    bal_h = head_h + m(10) + num_h + cap_h + 2 * PAD
    gap = m(12)
    box_w = (W - gap) // 2
    ap.append((body, SUI.group("SkyyBBal", "Left", h=bal_h, anchor={"bottom": m(16)})))
    for box, num, head, cap, left in (("SkyyBPurseBox", "SkyyBPurse", "Purse", "coins you carry - lost in part when you die", None),
                                      ("SkyyBBankBox", "SkyyBBalance", "Bank", "coins in the bank - safe when you die", {"left": gap})):
        ap.append(("SkyyBBal", SUI.panel(box, "well", w=box_w, h=bal_h, pad=PAD, anchor=left)))
        ap.append((box, SUI.label(None, head, "subtitle", h=head_h, size=FS["subtitle"], align="Center", anchor={"bottom": m(10)})))
        ap.append((box, SUI.label(num, "", "display", h=num_h, size=FS["display"], align="Center")))
        ap.append((box, SUI.label(None, cap, "caption", h=cap_h, size=FS["caption"], align="Center")))

    # 3. interest: one well - the rate (the vanilla heading, one line), the next payout time, the payout line. #SkyyBGain colour
    #    (review finding 7 / review 2 finding 1): success green only when payoutOn(), the label grey for gainText()'s hints, error
    #    red when the account file cannot be read. readable / bank / pct / max are the 0.1.3 prelude's locals.
    int_rows = [m(28), m(26), m(26)]
    int_h = sum(int_rows) + 2 * PAD
    ap.append((body, SUI.panel("SkyyBInt", "well", h=int_h, pad=PAD, anchor={"bottom": m(16)})))
    ap.append(("SkyyBInt", SUI.label("SkyyBRate", "", "heading", h=int_rows[0], size=FS["heading"], align="Center", wrap=False)))
    ap.append(("SkyyBInt", SUI.label("SkyyBNext", "", "default", h=int_rows[1], size=FS["text"], align="Center")))
    gain_col = SUI.J('!readable ? "%s" : (payoutOn(readable, gain, on) ? "%s" : "%s")'
                     % (SUI.COLOR["error"], SUI.COLOR["success"], SUI.COLOR["text"]), SUI.COLOR["success"])
    ap.append(("SkyyBInt", SUI.label("SkyyBGain", "", "bold", h=int_rows[2], size=FS["text"], align="Center", col=gain_col)))

    # 4. controls, 0.1.5 order (Skyy 2026-09-30): Deposit all | Deposit | Amount | Withdraw | Withdraw all - three groups
    #    ([Deposit all] [Deposit Amount Withdraw] [Withdraw all]), 18 px between them, 7 inside the middle one; Primary for the
    #    deposits, Secondary for the withdrawals (0.1.4's kinds); the amount box takes the rest of the row, centred on the 48 px row
    ctl_h = BH
    g_out, g_in = m(16), m(6)
    field_h = m(SUI.FIELD_H)              # 42: the vanilla 38 px text field x 1.1
    field_w = W - 2 * WIDE - 2 * BTN - 2 * g_out - 2 * g_in
    field_top = (ctl_h - field_h) // 2
    assert field_w >= m(240), "the amount box is too narrow: %d px" % field_w
    ap.append((body, SUI.group("SkyyBCtl", "Left", h=ctl_h)))
    ap.append(("SkyyBCtl", SUI.button("SkyyBDepAll", "Deposit all", "primary", BSZ, w=WIDE, anchor={"right": g_out})))
    ap.append(("SkyyBCtl", SUI.button("SkyyBDep", "Deposit", "primary", BSZ, w=BTN, anchor={"right": g_in})))
    ap.append(("SkyyBCtl", SUI.text_field("SkyyBAmtBox", "SkyyBAmount", w=field_w, h=field_h, size=FS["field"], placeholder="Amount",
                                          max_length=16, anchor={"top": field_top, "right": g_in})))
    ap.append(("SkyyBCtl", SUI.button("SkyyBWd", "Withdraw", "secondary", BSZ, w=BTN, anchor={"right": g_out})))
    ap.append(("SkyyBCtl", SUI.button("SkyyBWdAll", "Withdraw all", "secondary", BSZ, w=WIDE)))

    # 5. captions under the controls (top 4), each as wide as its control group: the middle one (b.set: it has commas and dots)
    #    spans Deposit + Amount + Withdraw, the group it explains
    capr_h, mid_w = m(25), BTN + g_in + field_w + g_in + BTN
    ap.append((body, SUI.group("SkyyBCap", "Left", h=capr_h, anchor={"top": m(4)})))
    ap.append(("SkyyBCap", SUI.label(None, "your whole purse", "caption", w=WIDE, h=capr_h, size=FS["caption"], align="Center",
                                     anchor={"right": g_out})))
    ap.append(("SkyyBCap", SUI.label("SkyyBCapMid", "", "caption", w=mid_w, h=capr_h, size=FS["caption"], align="Center",
                                     anchor={"right": g_out})))
    ap.append(("SkyyBCap", SUI.label(None, "your whole bank", "caption", w=WIDE, h=capr_h, size=FS["caption"], align="Center")))

    # 6. the result line (+ / - / = colours from the kit, two lines) and the chat hint
    ap.append((body, SUI.status_line("SkyyBInfo", "colorOf(this.info)", h=BANK_TWO_LINES, size=FS["status"], wrap=True,
                                     anchor={"top": m(12)})))
    ap.append((body, SUI.label("SkyyBChat", "", "caption", h=m(25), size=FS["caption"], align="Center")))

    # 7. footer (WorldEventPanelPage #Footer): content separator, Refresh | the flex spacer Group as a fixed width | Close (Secondary
    #    + the vanilla cancel sound)
    ap.append((body, SUI.separator("content", anchor={"top": m(SUI.SEP_MARGIN), "bottom": m(SUI.SEP_MARGIN)})))
    ap.append((body, SUI.group("SkyyBBottom", "Left", h=BH)))
    ap.append(("SkyyBBottom", SUI.button("SkyyBRefresh", "Refresh", "secondary", BSZ, w=BTN, anchor={"right": m(4)})))
    ap.append(("SkyyBBottom", SUI.spacer(w=W - 2 * BTN - 2 * m(4), h=BH)))
    ap.append(("SkyyBBottom", SUI.button("SkyyBClose", "Close", "secondary", BSZ, w=BTN, sound="cancel", anchor={"left": m(4)})))

    # the budget, read back out of the markup (bank_outer): the body column, every row and every well filled exactly
    bank_filled(ap, body, "h", sh.inner_h, "bank page body (BANK_H = 38 + 2 x BANK_PAD + the body)")
    for row, row_h in (("SkyyBBal", bal_h), ("SkyyBCtl", ctl_h), ("SkyyBCap", capr_h), ("SkyyBBottom", BH)):
        bank_filled(ap, row, "w", W, "row " + row, cross=row_h)
    for well, inner in (("SkyyBPurseBox", bal_h - 2 * PAD), ("SkyyBBankBox", bal_h - 2 * PAD), ("SkyyBInt", int_h - 2 * PAD)):
        bank_filled(ap, well, "h", inner, "well " + well)
    # 0.1.5: the controls in Skyy's order, and each caption exactly under its controls (x positions read back out of the markup)
    ctl = bank_spans(ap, "SkyyBCtl")
    assert [i for i, _a, _b in ctl] == BANK_CTL_ORDER, "controls row order: %s" % [i for i, _a, _b in ctl]
    at = dict((i, (a, b)) for i, a, b in ctl)
    caps = [(a, b) for _i, a, b in bank_spans(ap, "SkyyBCap")]
    want = [at["SkyyBDepAll"], (at["SkyyBDep"][0], at["SkyyBWd"][1]), at["SkyyBWdAll"]]
    assert caps == want, "the captions must sit under their controls: %s, controls %s" % (caps, want)
    # every button label fits its button minus the 2 x 24 px padding at the kit's label size (the client's font tables)
    lsz, _bh, bpad = SUI.BUTTON_SIZES[BSZ]
    n_btn = 0
    for _p, mk in ap:
        r = SUI.render(mk)
        mb = re.match(r"TextButton #([A-Za-z0-9]+) \{ Anchor: \(Width: (\d+)", r)
        if mb:
            text = re.search(r'Text: "([^"]*)"', r).group(1)
            need = SUI.text_width(text, lsz, bold=True, upper=True)
            assert need <= int(mb.group(2)) - 2 * bpad, "button #%s %r: %.0f px of label, %d px of room" % (
                mb.group(1), text, need, int(mb.group(2)) - 2 * bpad)
            n_btn += 1
    assert n_btn == 6, "6 buttons (%d)" % n_btn
    # every Anchor margin this page writes (the frame's own values aside) is a vanilla step x 1.1 (plus the 3 px that centres the
    # 42 px amount box on the 48 px row); only properties the deployed pages or the probe pages prove (the kit's one table)
    for _p, mk in ap[n_frame:]:
        for anc in re.findall(r"Anchor: \(([^)]*)\)", SUI.render(mk)):
            for k, v in re.findall(r"(Left|Right|Top|Bottom|Horizontal|Vertical|Full): (-?\d+)", anc):
                assert int(v) in BANK_STEPS or (k, int(v)) in (("Full", 0), ("Top", field_top)), "margin %s: %s is no step" % (k, v)
    SUI.assert_proven(ap, what="bank page")
    assert BANK_H - SUI.DECO_TOP - SUI.DECO_BOTTOM <= 1080, "the page with its ornaments must fit a 1080 px screen"
    ap.check(BANK_PREFIX)                                            # ids, prefix, no duplicates, parents exist, markup rules
    have = set(i for _p, mk in ap for i in re.findall(r"#([A-Za-z0-9]+)\s*\{", SUI.render(mk)))
    missing = [i for i in BANK_IDS_013 if i not in have]
    assert not missing, "0.1.5 dropped 0.1.3 element ids: %s" % missing
    sets = [(ident, "Text", SUI.J(expr) if not expr.startswith('"') else SUI.java_unlit(expr)) for ident, expr in BANK_SETS_013]
    assert all(ident in have for ident, _pr, _v in sets), "a b.set target is not on the page"
    return sh, sets


BANK_SH, BANK_SET_LINES = bank_page()
