# 0.1.6: the ONE way the page answers. Never from a closed page (a stray page packet is what leaves the game waiting for an
# acknowledgement that never comes); rebuild() is the engine's (CustomUIPage.rebuild: build + PageManager.updateCustomPage), which
# silently does nothing without a player reference - said in the log instead; if the rebuild throws, a short update with only the
# result line still unlocks the client.
PM(r"""
public void answer() {
  if (this.dismissed) { @PKG@.BankStore.warn("bank page answer for " + name() + " not sent: the page is already closed"); return; }
  boolean sent = false;
  try {
    if (this.playerRef.getReference() == null) {
      @PKG@.BankStore.warn("bank page answer for " + name() + " not sent: the player is between worlds (the game closes the page at a world change)");
      return;
    }
    rebuild();
    sent = true;
  } catch (Throwable t) {
    @PKG@.BankStore.warn("bank page answer for " + name() + " failed, sending the short answer instead: " + t);
  }
  if (sent) return;
  try {
    @UCB@ b = new @UCB@();
    b.set("#SkyyBInfo.Text", "Something went wrong drawing the bank page - press Esc and open /bank again.");
    sendUpdate(b, false);
    this.lastSend = System.currentTimeMillis();
  } catch (Throwable t2) { @PKG@.BankStore.warn("bank page short answer for " + name() + " failed: " + t2); }
}""")
# 0.1.6: the page check, on the player's world thread (BankWatch hands it here). true = keep checking.
#  - the page is no longer the open page (closed / replaced) -> done;
#  - the player is in another world than the page was opened in -> the client dropped the page at the world change; forget it on the
#    server the way the client's Esc does (PageManager.handleEvent Dismiss: onDismiss + customPage = null, no packet, no counter
#    change), so no later setPage can add an acknowledgement the client never sends;
#  - SETTLE after the page's last packet: a test click through the engine's own gate (PageManager.handleEvent Data -> this page's
#    handleDataEvent only while customPageRequiredAcknowledgments == 0). It arrives -> healthy, nothing is sent. It does not ->
#    the game is dropping this page's clicks: log, PageManager.clearCustomPageAcknowledgements() (what a world change runs) and an
#    answer, so the client's "Loading..." ends and the next click reaches the bank.
PM(r"""
public boolean watchTick(@WLD@ now) {
  if (this.dismissed) return false;
  @REF@ ref = this.playerRef.getReference();
  if (ref == null || !ref.isValid()) return true;
  @ST@ st = ref.getStore();
  if (st == null) return true;
  @PLA@ p = (@PLA@) st.getComponent(ref, @PLA@.getComponentType());
  if (p == null) return true;
  @PGM@ pm = p.getPageManager();
  if (pm == null) return true;
  if (pm.getCustomPage() != this) return false;
  if (this.world != null && now != null && now != this.world) {
    pm.handleEvent(ref, st, new @CPE@(@CPT@.Dismiss, (String) null));
    @PKG@.BankStore.info("the bank page of " + name() + " was still open on the server after a world change (the client closes every page at a world change) - forgot it on the server too (no packet), so no later bench or page close leaves the game waiting for an answer that never comes");
    return false;
  }
  long t = System.currentTimeMillis();
  if (t - this.lastSend < SETTLE) return true;
  this.probeNonce = Long.toHexString(System.nanoTime() ^ this.base);
  this.probeSeen = false;
  pm.handleEvent(ref, st, new @CPE@(@CPT@.Data, "{\"a\":\"skyybankcheck\",\"n\":\"" + this.probeNonce + "\"}"));
  if (this.probeSeen) return true;
  if (pm.getCustomPage() != this) return false;
  this.heals = this.heals + 1;
  if (this.heals <= 3 || this.heals % 60 == 0) @PKG@.BankStore.warn("the game was dropping " + name() + "'s bank page clicks (it still waited for a page acknowledgement the client will never send - a page left open across a world change); reset the page acknowledgements and answered the page (" + this.heals + ")");
  pm.clearCustomPageAcknowledgements();
  this.info = "=The game was holding back this page's clicks (a hiccup after a teleport) - fixed. If a click did nothing, nothing was moved - click again.";
  answer();
  return true;
}""")
# 0.1.6: EVERY click is answered (answer() at the end) except Close (it closes the page) and the page's own check click. A coin click
# is honoured only with the page's current token ("t"), which is used up before coins move (once per click), and only while the
# player is still on the profile the page was drawn for. Unknown / malformed clicks and errors are answered too; errors are logged.
PM(r"""
public void handleDataEvent(@REF@ ref, @ST@ st, String data) {
  String a = "";
  try {
    a = data == null ? "" : jsonStr(data, "a");
    if (a.equals("skyybankcheck")) {
      String n = jsonStr(data, "n");
      if (this.probeNonce != null && this.probeNonce.length() > 0 && n.equals(this.probeNonce)) { this.probeSeen = true; return; }
      a = "?";
    }
    if (a.equals("close")) {
      boolean closed = false;
      try {
        if (this.playerRef.getReference() != null) { close(); closed = true; }
      } catch (Throwable tc) { @PKG@.BankStore.warn("bank page Close failed for " + name() + ": " + tc); }
      if (closed) return;
      this.info = "-The page could not be closed from here - press Esc.";
    } else if (this.dismissed) {
      this.info = "=This bank page was already closed, so nothing was moved.";
    } else {
      this.handled = this.handled + 1;
      java.util.UUID u = this.playerRef.getUuid();
      String t = typed(data);
      String res = null;
      this.keepAmount = t;
      if (a.equals("depall") || a.equals("wdall") || a.equals("deposit") || a.equals("withdraw")) {
        String ct = data == null ? "" : jsonStr(data, "t");
        if (this.tok == null || !this.tok.equals(ct)) {
          res = "=That click was for an older copy of this page, so nothing was moved. The page is up to date now - click again if you meant it.";
        } else if (!profileStill(u)) {
          res = "=Your profile changed after this page opened, so nothing was moved. The page now shows your current profile - click again.";
        } else {
          this.tok = null;
          res = coinClick(u, a, t);
        }
      } else if (a.equals("refresh")) {
        res = "";
      } else if (a.equals("amount")) {
        if (t.length() == 0) res = "=Type an amount (500, 2k, 1.5m or all), then click Deposit or Withdraw.";
        else res = "=Click Deposit or Withdraw to move " + t + " coins. Enter alone never moves coins.";
      } else {
        res = "=That button is not part of this page any more - the page was redrawn. Nothing was moved.";
      }
      this.info = res == null ? "" : res;
    }
  } catch (Throwable ex) {
    @PKG@.BankStore.warn("bank page click '" + a + "' failed for " + name() + ": " + ex);
    this.info = "-Something went wrong - check your purse and bank above. The server log has the details.";
  }
  answer();
}""")


# ================= BankWatch part 2 (0.1.6): the scheduler-thread tick -> the world thread
WM(r"""
public void hop() {
  if (STOP || this.page.dismissed) return;
  @PR@ pr = this.page.who();
  if (pr == null || !pr.isValid()) return;
  java.util.UUID wu = pr.getWorldUuid();
  @UNI@ uni = @UNI@.get();
  @WLD@ w = null;
  if (wu != null && uni != null) w = uni.getWorld(wu);
  if (w == null) { schedule(this.page); return; }
  w.execute(new @PKG@.BankWatch(this.page, w));
}""")
WM(r"""
public void run() {
  if (this.target == null) {
    try { hop(); }
    catch (Throwable t) { if (this.page.watchFail(t)) schedule(this.page); }
    return;
  }
  boolean again = false;
  try { again = this.page.watchTick(this.target); }
  catch (Throwable t) { again = this.page.watchFail(t); }
  if (again) schedule(this.page);
}""")

