# 0.1.1: shared body (was BankConfigCmd.execute in 0.1). pctText == null -> show; minText/maxText == null -> keep current.
adm.addMethod(CtNewMethod.make(f"""
public static void apply({PR} pr, String pctText, String minText, String maxText) {{
  try {{
    if (pctText == null) {{
      String nextIn = {PKG}.BankConfig.durText({PKG}.BankConfig.LAST + {PKG}.BankConfig.interval() - System.currentTimeMillis());
      pr.sendMessage({MSG}.raw("[Bank] interest " + {PKG}.BankConfig.describe() + "; next payout " + nextIn + ". All settings: SkyWynn Menu -> Server Setup -> Bank. /bankconfig <bracket 1 percent> <minutes> [maxPrincipal]"));
      return;
    }}
    String pc = pctText.replace("%", "").trim();
    double pd = Double.parseDouble(pc);
    long mn = minText != null ? Long.parseLong(minText.trim()) : -1L;
    long mp = maxText != null ? {PKG}.BankCmd.parseAmount(maxText, {PKG}.BankConfig.MAX_PRINCIPAL) : -1L;
    if (!(pd >= 0.0 && pd <= 100.0) || (minText != null && (mn < 1L || mn > 10080L)) || (maxText != null && (mp < 0L || mp > 1000000000000L))) {{ pr.sendMessage({MSG}.raw("[Bank] percent 0-100, minutes 1-10080, maxPrincipal 0..1,000,000,000,000")); return; }}
    // fix round (critic 2 finding 3): a command never makes payouts MORE often (the old "/bankconfig 2 60" habit would bring back
    // the hourly payouts in one step, without the question Server Setup asks); nothing is changed then
    if (minText != null && mn * 60000L < {PKG}.BankConfig.interval()) {{ pr.sendMessage({MSG}.raw("[Bank] Nothing changed: " + mn + " min would pay interest more often than now (" + {PKG}.BankConfig.cadence({PKG}.BankConfig.interval()) + "). Make payouts more often in SkyWynn Menu -> Server Setup -> Bank -> Time between payouts (it asks first).")); return; }}
    java.util.UUID who = pr.getUuid();
    String nm = pr.getUsername();
    StringBuilder sb = new StringBuilder("[Bank] ");
    sb.append({PKG}.CfgFn.cmdSet("interestPercent", pc, who, nm));
    if (minText != null) sb.append(" (").append(mn).append(" min = ").append(mn * 60L).append(" s) ").append({PKG}.CfgFn.cmdSet("intervalSeconds", String.valueOf(mn * 60L), who, nm));
    if (maxText != null) sb.append(" ").append({PKG}.CfgFn.cmdSet("maxPrincipal", String.valueOf(mp), who, nm));
    pr.sendMessage({MSG}.raw(sb.toString()));
  }} catch (Throwable t) {{ pr.sendMessage({MSG}.raw("[Bank] Usage: /bankconfig <percent> <minutes> [maxPrincipal]")); }}
}}""", adm))
